import torch
import torch.nn as nn

class DSLPortfolioNet(nn.Module):
    def __init__(self, input_dim, num_assets):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(input_dim, 64),
            nn.ReLU(),
            nn.Linear(64, num_assets)  # Raw logits
        )

    def forward(self, x):
        # Softmax ensures weights are non-negative and sum to 1
        return torch.softmax(self.net(x), dim=-1)

# Loss function: Cross-Entropy between predicted and target weights
def dsl_loss(pred_weights, target_weights):
    eps = 1e-15
    pred_weights = torch.clamp(pred_weights, eps, 1 - eps)
    return -torch.sum(target_weights * torch.log(pred_weights), dim=-1).mean()
